import redis
import json
from datetime import datetime, timedelta

class SessionCache:
    def __init__(self, redis_host='localhost', redis_port=6379):
        self.redis_client = redis.Redis(host=redis_host, port=redis_port, decode_responses=True)
        self.ttl = 3600  # 1 hour

    def set_session(self, token, user_id, metadata=None):
        """Store session data with token as the key"""
        session_data = {
            'user_id': user_id,
            'created_at': datetime.utcnow().isoformat(),
            'metadata': metadata or {}
        }
        # Direct token as key for maximum performance
        self.redis_client.setex(token, self.ttl, json.dumps(session_data))

    def get_session(self, token):
        """Retrieve session by token"""
        data = self.redis_client.get(token)
        if data:
            return json.loads(data)
        return None

    def delete_session(self, token):
        """Invalidate session"""
        self.redis_client.delete(token)

# Usage
cache = SessionCache()
cache.set_session('abc123def456', user_id=42, metadata={'ip': '192.168.1.1'})
session = cache.get_session('abc123def456')
print(session)
